import { useState, type FormEvent } from 'react';
import './sign-in.css';

type Status = 'idle' | 'sso' | 'password' | 'error';

export function App() {
  const [status, setStatus] = useState<Status>('idle');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const invalid = status === 'error';
  const busy = status === 'sso' || status === 'password';

  function startSso() {
    setStatus('sso');
    // Hand off to the company identity provider.
    window.location.assign('/auth/sso');
  }

  async function submitPassword(e: FormEvent) {
    e.preventDefault();
    if (!email || !password) {
      setStatus('error');
      return;
    }
    setStatus('password');
    try {
      const res = await fetch('/auth/password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });
      if (!res.ok) throw new Error('rejected');
      window.location.assign('/');
    } catch {
      setStatus('error');
    }
  }

  return (
    <main className="container sign-in">
      <div className="card card-pad-lg sign-in-card">
        <h1>Sign in</h1>
        <p className="lede">Use your company account to continue.</p>

        <button
          type="button"
          className={`btn btn-primary btn-lg btn-block${status === 'sso' ? ' is-loading' : ''}`}
          onClick={startSso}
          disabled={busy}
        >
          Continue with SSO
        </button>
        <p className="muted sign-in-hint">Recommended. Your identity provider handles verification.</p>

        <hr className="hr" />

        <form className="stack sign-in-form" onSubmit={submitPassword} noValidate>
          <h2 className="label">Email and password</h2>

          {invalid && (
            <div className="alert" data-tone="danger" role="alert">
              <p className="alert-title">Sign-in failed</p>
              <p className="alert-body">Check your email and password, then try again.</p>
            </div>
          )}

          <div className="stack">
            <label htmlFor="email">Email</label>
            <input
              id="email"
              className="input"
              type="email"
              autoComplete="username"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              aria-invalid={invalid && !email ? true : undefined}
            />
          </div>

          <div className="stack">
            <label htmlFor="password">Password</label>
            <input
              id="password"
              className="input"
              type="password"
              autoComplete="current-password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              aria-invalid={invalid && !password ? true : undefined}
            />
          </div>

          <button
            type="submit"
            className={`btn btn-secondary btn-block${status === 'password' ? ' is-loading' : ''}`}
            disabled={busy}
          >
            Sign in
          </button>
        </form>
      </div>
    </main>
  );
}

.sign-in {
  min-block-size: 100vh;
  display: grid;
  place-items: center;
  padding-block: var(--space-12);
}

.sign-in-card {
  inline-size: 100%;
  max-inline-size: calc(var(--container-sm) / 1.5);
}

.sign-in-card h1 {
  margin: 0 0 var(--space-2);
}

.sign-in-card .lede {
  margin: 0 0 var(--space-6);
}

.sign-in-hint {
  margin: var(--space-3) 0 0;
}

.sign-in-card .hr {
  margin-block: var(--space-6);
}

.sign-in-form > .stack {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.sign-in-form {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.sign-in-form h2 {
  margin: 0;
}
